CREATE TABLE public.operational_worker_credentials (id boolean PRIMARY KEY DEFAULT true CHECK(id), token text NOT NULL DEFAULT (gen_random_uuid()::text || gen_random_uuid()::text));
GRANT ALL ON public.operational_worker_credentials TO service_role;
ALTER TABLE public.operational_worker_credentials ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.operational_worker_headers() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE secret text; BEGIN INSERT INTO public.operational_worker_credentials(id) VALUES(true) ON CONFLICT DO NOTHING; SELECT token INTO secret FROM public.operational_worker_credentials WHERE id=true; RETURN jsonb_build_object('Content-Type','application/json','x-operational-secret',secret); END; $$;
REVOKE ALL ON FUNCTION public.operational_worker_headers() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.operational_worker_headers() TO service_role;
ALTER TABLE public.image_processing_jobs ADD COLUMN claim_token uuid, ADD COLUMN lease_expires_at timestamptz;
REVOKE UPDATE ON public.image_processing_jobs FROM authenticated;
CREATE OR REPLACE FUNCTION public.claim_image_processing_jobs(_limit integer DEFAULT 5) RETURNS SETOF public.image_processing_jobs LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.image_processing_jobs SET status='error',error='Processing lease expired; retry required',lease_expires_at=NULL,claim_token=NULL WHERE status='processing' AND coalesce(lease_expires_at,updated_at+interval '10 minutes') < now() AND attempts>=3; RETURN QUERY WITH candidates AS (SELECT id FROM public.image_processing_jobs WHERE attempts<3 AND (status IN ('pending','retry') OR (status='processing' AND coalesce(lease_expires_at,updated_at+interval '10 minutes')<now())) ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT greatest(1,least(_limit,5))) UPDATE public.image_processing_jobs j SET status='processing',attempts=j.attempts+1,claim_token=gen_random_uuid(),lease_expires_at=now()+interval '10 minutes' FROM candidates c WHERE j.id=c.id RETURNING j.*; END; $$;
REVOKE ALL ON FUNCTION public.claim_image_processing_jobs(integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.claim_image_processing_jobs(integer) TO service_role;
CREATE OR REPLACE FUNCTION public.unresolved_catalog_security_scan() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH latest AS (SELECT findings FROM public.security_scan_runs WHERE status='ok' ORDER BY created_at DESC,id DESC LIMIT 1) SELECT r.id FROM public.security_scan_runs r WHERE r.status='ok' AND r.high_regression AND NOT EXISTS(SELECT 1 FROM public.catalog_security_approvals a WHERE a.scan_id=r.id) AND EXISTS (SELECT 1 FROM jsonb_array_elements(r.findings) f CROSS JOIN latest l CROSS JOIN LATERAL jsonb_array_elements(l.findings) c WHERE f->>'severity' IN ('high','critical') AND c->>'severity' IN ('high','critical') AND f->>'id'=c->>'id' AND f->>'package'=c->>'package') ORDER BY r.created_at DESC,r.id DESC LIMIT 1; $$;
REVOKE ALL ON FUNCTION public.unresolved_catalog_security_scan() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.catalog_security_status() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE blocked_scan uuid; enabled boolean; BEGIN IF NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'editor')) THEN RAISE EXCEPTION 'Access denied' USING ERRCODE='42501'; END IF; SELECT coalesce(block_catalog,true) INTO enabled FROM public.operational_settings WHERE id=true; blocked_scan:=public.unresolved_catalog_security_scan(); RETURN jsonb_build_object('blocked',coalesce(enabled,true) AND blocked_scan IS NOT NULL,'scan_id',blocked_scan,'approved',false); END; $$;
CREATE OR REPLACE FUNCTION public.enforce_catalog_security() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce((SELECT block_catalog FROM public.operational_settings WHERE id=true),true) AND public.unresolved_catalog_security_scan() IS NOT NULL THEN RAISE EXCEPTION 'Catalog blocked: unresolved high security regression. Request approval in Admin Security.' USING ERRCODE='42501'; END IF; RETURN NULL; END; $$;
CREATE OR REPLACE FUNCTION public.approve_catalog_security(_scan_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin access required' USING ERRCODE='42501'; END IF; IF _reason IS NULL OR length(btrim(_reason))<10 THEN RAISE EXCEPTION 'Provide a detailed approval reason'; END IF; IF _scan_id IS NULL OR _scan_id IS DISTINCT FROM public.unresolved_catalog_security_scan() THEN RAISE EXCEPTION 'Blocking scan changed, refresh first'; END IF; INSERT INTO public.catalog_security_approvals(scan_id,approved_by,reason) VALUES(_scan_id,auth.uid(),btrim(_reason)) ON CONFLICT(scan_id) DO NOTHING; END; $$;